  const W=2600,H=2600,skins=[{name:'Rookie',color:'#f4a66f',accent:'#ffe0aa'},{name:'Volt',color:'#68d9c8',accent:'#e5fff2'},{name:'Ranger',color:'#8abb61',accent:'#e7f2a0'},{name:'Nova',color:'#ba83db',accent:'#f2caff'},{name:'Blaze',color:'#ef735c',accent:'#ffd18b'},{name:'Frost',color:'#79b9e8',accent:'#d9f4ff'},{name:'Shadow',color:'#546b7d',accent:'#d6e5e9'},{name:'Sunny',color:'#e4c94f',accent:'#fff2a1'}];
